10	fn pronoun_for_symbol(
11	    symbol_flags: SymbolFlags,
12	) -> (/* singular */ &'static str, /* plural */ &'static str) {
13	    if symbol_flags.is_function() {
14	        ("Function", "functions")
15	    } else if symbol_flags.is_class() {
16	        ("Class", "classes")
17	    } else if symbol_flags.is_interface() {
18	        ("Interface", "interfaces")
19	    } else if symbol_flags.is_type_alias() {
20	        ("Type alias", "type aliases")
21	    } else if symbol_flags.is_enum() {
22	        ("Enum", "enums")
23	    } else if symbol_flags.is_enum_member() {
24	        ("Enum member", "enum members")
25	    } else if symbol_flags.is_type_import() {
26	        ("Type", "types")
27	    } else if symbol_flags.is_import() {
28	        ("Identifier", "identifiers")
29	    } else if symbol_flags.is_catch_variable() {
30	        ("Catch parameter", "caught errors")
31	    } else {
32	        ("Variable", "variables")
33	    }
34	}
